#include <stack>
#include <vector>
#include <iostream>

int main() {
    std::vector<int> source = {1, 2, 3};

    // Stack initialization performs a deep copy of 'source'
    std::stack<int, std::vector<int>> s(source);

    // Modifying the source does NOT affect the stack
    source.push_back(99);

    std::cout << "Stack size: " << s.size() << " (Still 3)\n";
    std::cout << "Source size: " << source.size() << " (Now 4)\n";
}
